export declare const isObject: (val: unknown) => val is Record<PropertyKey, any>;
export declare const isFunction: (val: unknown) => val is (...args: any[]) => any;
export declare const isString: (val: unknown) => val is string;
export declare const isBoolean: (val: unknown) => val is boolean;
export declare const isNumber: (val: unknown) => val is number;
export declare const isUndef: (val: unknown) => val is undefined;
export declare const isNonNullable: <T>(val: T) => val is NonNullable<T>;
export declare const isThenable: <T>(val: any) => val is PromiseLike<T>;
